import{_ as a,a as t,c as n,ac as r}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 40 Waves","description":"学习 where 的地点与条件意义，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 40 Waves","description":"学习 where 的地点与条件意义，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 where 的地点与条件意义，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 39 What every writer wants","link":"/life/english/new-concept/book-4/unit-05/lesson-039"},"next":{"text":"第四册：流利英语 · Lesson 41 Training elephants","link":"/life/english/new-concept/book-4/unit-06/lesson-041"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 39 What every writer wants","link":"/life/english/new-concept/book-4/unit-05/lesson-039"},"next":{"text":"第四册：流利英语 · Lesson 41 Training elephants","link":"/life/english/new-concept/book-4/unit-06/lesson-041"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-05/lesson-040.md","filePath":"life/english/new-concept/book-4/unit-05/lesson-040.md"}'),i={name:"life/english/new-concept/book-4/unit-05/lesson-040.md"};function o(s,e,l,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="第四册-流利英语-·-lesson-40-waves" tabindex="-1">第四册：流利英语 · Lesson 40 Waves <a class="header-anchor" href="#第四册-流利英语-·-lesson-40-waves" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 40 Waves&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元 5</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以波浪主题练习机制和条件阅读，区分日常看到的水面运动与对传播过程的解释。不要把一种模型在有限条件下的结论扩展到所有波或所有水域。重点识别 where 引导的条件性表达，准确区分地点限制与“在某种情况下”的抽象用法。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>wave</td><td>/weɪv/</td><td>n.</td><td>波浪</td><td>a surface wave</td></tr><tr><td>ripple</td><td>/ˈrɪpəl/</td><td>n.</td><td>涟漪</td><td>small ripples</td></tr><tr><td>pattern</td><td>/ˈpætən/</td><td>n.</td><td>图案；模式</td><td>a wave pattern</td></tr><tr><td>boundary</td><td>/ˈbaʊndəri/</td><td>n.</td><td>边界</td><td>a fixed boundary</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>travel through — 穿过某介质传播</li><li>under these conditions — 在这些条件下</li></ul><h2 id="语法讲解-where-的地点与条件意义" tabindex="-1">语法讲解：where 的地点与条件意义 <a class="header-anchor" href="#语法讲解-where-的地点与条件意义" aria-label="Permalink to &quot;语法讲解：where 的地点与条件意义&quot;">​</a></h2><p>where 可以引导地点从句，也可在正式论述中表示“在……情况下”。Where the surface is uneven, the pattern becomes harder to interpret. 既可指表面不平的区域，也可泛指这种条件；语境决定侧重点。不能把 where 任意代替 when：时间应优先用 when，明确假设可用 if。关系从句中的 where 相当于 in/at which，只有先行词和介词关系合理时才可转换。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Where the water meets the barrier, the pattern changes.</p></blockquote><p>在水与障碍物相接的地方，波纹形态发生变化。</p><p>where 从句指地点；主句 the pattern changes 描述该区域的观察结果。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不要把“实验结束时”写成 where the experiment ends；普通时间关系应写 when the experiment ends。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读 Where the water meets the barrier 时保持一个意群；重读 meets 与 changes，区分位置条件和观察结果。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Small ripples spread across the tray. Where they meet the edge, the visible pattern changes. This observation describes our model and does not cover every kind of wave.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>根据下面给出的原创文字情境，改写三句观察：小涟漪在浅盘中向四周扩散；到达盘边时，可见的波纹形态发生变化；这些描述只适用于这个模型。用 where 从句说明变化发生的位置，并在末句保留模型范围的限制，不补写文字中未给出的速度、高度或原因。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句改写文字情境中的扩散，第二句用 where 从句指出盘边这一变化位置，第三句保留模型边界。任务只依据本页文字，不要求实际演示或图示，也不把给定情境当作所有水波的普遍规律。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中的 where 主要表示地点还是时间？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 地点。</p><p><strong>解析：</strong> 它指水与障碍物相接的位置。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：___ the demonstration ends, record your observations.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> When</p><p><strong>解析：</strong> 演示结束是时间条件。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 the place where the waves meet 改为介词加 which。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the place at which the waves meet</p><p><strong>解析：</strong> where 指会合地点，可用 at which。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：where 的地点与条件意义。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-039">上一课</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-06/lesson-041">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",o]]);export{u as __pageData,b as default};
